/**
 * The hidden polite status line of spec/07 §4.3 (D116 (1)): [text] is announced by TalkBack when it changes, without
 * moving the focus, and nothing is drawn (a 1 dp node: a node of size zero may be left out of the accessibility tree).
 * null or empty says nothing. Not for errors (they stand in the view, spec/07 §4.1) and not for a removed entry (it
 * keeps its toast with „Rückgängig“, D105 (35), D119 (1)).
 */
@Composable
fun SbStatusRegion(text: String?, modifier: Modifier = Modifier) {
    Box(
        modifier
            .size(1.dp)
            .clearAndSetSemantics {
                liveRegion = LiveRegionMode.Polite
                if (!text.isNullOrEmpty()) contentDescription = text
            },
    )
}
